import javax.servlet.http.*;
import javax.servlet.annotation.WebServlet;
import java.sql.*;

// BAD: Improper use of JDBC API (string concatenation) causes SQL Injection
@WebServlet("/login-bad")
public class BadLoginServlet extends HttpServlet {
  @Override
  protected void doPost(HttpServletRequest req, HttpServletResponse resp) throws java.io.IOException {
    String user = req.getParameter("user");
    String pass = req.getParameter("pass");

    try (Connection conn = DriverManager.getConnection("jdbc:postgresql://localhost/app", "app", "app")) {
      Statement stmt = conn.createStatement();
      // vulnerable: concatenating untrusted input enables SQL injection
      String sql = "SELECT id FROM users WHERE username = '" + user + "' AND password_hash = '" + pass + "'";
      ResultSet rs = stmt.executeQuery(sql);

      if (rs.next()) {
        resp.getWriter().println("Welcome " + user); // Also reflects untrusted input (potential XSS)
      } else {
        resp.setStatus(HttpServletResponse.SC_UNAUTHORIZED);
        resp.getWriter().println("Invalid credentials");
      }
    } catch (SQLException e) {
      resp.setStatus(HttpServletResponse.SC_INTERNAL_SERVER_ERROR);
      resp.getWriter().println("Server error");
    }
  }
}

