import javax.servlet.http.*;
import javax.servlet.annotation.WebServlet;
import java.sql.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;

// GOOD: Use PreparedStatement parameters and escape output
@WebServlet("/login")
public class SafeLoginServlet extends HttpServlet {
  @Override
  protected void doPost(HttpServletRequest req, HttpServletResponse resp) throws java.io.IOException {
    String user = req.getParameter("user");
    String pass = req.getParameter("pass");

    // Basic input checks to fail fast
    if (user == null || pass == null || user.length() > 64 || pass.length() > 256) {
      resp.setStatus(HttpServletResponse.SC_BAD_REQUEST);
      resp.getWriter().println("Bad request");
      return;
    }

    String passHash = hash(pass); // In production, use BCrypt/Argon2 instead of plain SHA-256

    try (Connection conn = DriverManager.getConnection("jdbc:postgresql://localhost/app", "app", "app")) {
      String sql = "SELECT id FROM users WHERE username = ? AND password_hash = ?";
      try (PreparedStatement ps = conn.prepareStatement(sql)) {
        ps.setString(1, user);
        ps.setString(2, passHash);

        try (ResultSet rs = ps.executeQuery()) {
          if (rs.next()) {
            String safeUser = htmlEscape(user); // Avoid XSS when reflecting input
            resp.getWriter().println("Welcome " + safeUser);
          } else {
            resp.setStatus(HttpServletResponse.SC_UNAUTHORIZED);
            resp.getWriter().println("Invalid credentials");
          }
        }
      }
    } catch (SQLException e) {
      resp.setStatus(HttpServletResponse.SC_INTERNAL_SERVER_ERROR);
      resp.getWriter().println("Server error");
    }
  }

  // Minimal HTML escape without external libs
  private static String htmlEscape(String s) {
    return s
      .replace("&", "&amp;")
      .replace("<", "&lt;")
      .replace(">", "&gt;")
      .replace("\"", "&quot;")
      .replace("'", "&#x27;");
  }

  // Simple hashing for demo only; use a proper password hasher in real apps
  private static String hash(String s) {
    try {
      MessageDigest md = MessageDigest.getInstance("SHA-256");
      byte[] digest = md.digest(s.getBytes(StandardCharsets.UTF_8));
      StringBuilder sb = new StringBuilder(digest.length * 2);
      for (byte b : digest) sb.append(String.format("%02x", b));
      return sb.toString();
    } catch (Exception e) {
      throw new RuntimeException(e);
    }
  }
}

