import java.io.IOException;
import javax.servlet.ServletException;
import javax.servlet.http.*;
import java.sql.*;

// Demonstrates improper use of Java's JDBC API causing SQL injection
public class LoginServlet extends HttpServlet {
  @Override
  protected void doPost(HttpServletRequest request, HttpServletResponse response)
      throws ServletException, IOException {

    String username = request.getParameter("user");
    String password = request.getParameter("pass");

    try {
      Connection conn = DriverManager.getConnection("jdbc:mysql://localhost:3306/app", "appuser", "apppass");
      Statement stmt = conn.createStatement();

      // vulnerable: user-controlled data is concatenated into SQL, enabling SQL injection
      String sql = "SELECT id FROM users WHERE username='" + username + "' AND password='" + password + "'";
      ResultSet rs = stmt.executeQuery(sql);

      if (rs.next()) {
        response.getWriter().println("Logged in as " + username); // Reflects untrusted input
      } else {
        response.getWriter().println("Login failed");
      }

      rs.close();
      stmt.close();
      conn.close();
    } catch (SQLException e) {
      throw new ServletException(e);
    }
  }
}
