import java.io.IOException;
import javax.servlet.ServletException;
import javax.servlet.http.*;
import java.sql.*;

// Fixed version using PreparedStatement to prevent SQL injection
public class LoginServlet extends HttpServlet {
  @Override
  protected void doPost(HttpServletRequest request, HttpServletResponse response)
      throws ServletException, IOException {

    String username = request.getParameter("user");
    String password = request.getParameter("pass");

    // Basic input validation to reduce attack surface
    if (username == null || password == null || username.length() > 64 || password.length() > 128) {
      response.sendError(HttpServletResponse.SC_BAD_REQUEST);
      return;
    }

    String sql = "SELECT id FROM users WHERE username=? AND password=?"; // Use parameter placeholders

    try (Connection conn = DriverManager.getConnection("jdbc:mysql://localhost:3306/app", "appuser", "apppass");
         PreparedStatement ps = conn.prepareStatement(sql)) {

      ps.setString(1, username); // Bind parameters instead of concatenating
      ps.setString(2, password); // In real apps, compare a hashed password (e.g., BCrypt)

      try (ResultSet rs = ps.executeQuery()) {
        if (rs.next()) {
          response.getWriter().println("Logged in"); // Avoid reflecting raw user input
        } else {
          response.getWriter().println("Login failed");
        }
      }
    } catch (SQLException e) {
      throw new ServletException("Database error", e);
    }
  }
}

